import functools

def semver_sort(versions):
    def parse(v):
        core = v
        pre = None
        if '+' in core:
            core, _ = core.split('+', 1)
        if '-' in core:
            core, pre = core.split('-', 1)
        major, minor, patch = (int(x) for x in core.split('.'))
        pre_ids = pre.split('.') if pre is not None else None
        return (major, minor, patch, pre_ids)

    def compare_id(a, b):
        a_num = a.isdigit()
        b_num = b.isdigit()
        if a_num and b_num:
            ai, bi = int(a), int(b)
            return -1 if ai < bi else (1 if ai > bi else 0)
        if a_num and not b_num:
            return -1
        if not a_num and b_num:
            return 1
        return -1 if a < b else (1 if a > b else 0)

    def compare(v1, v2):
        M1, m1, p1, pre1 = parse(v1)
        M2, m2, p2, pre2 = parse(v2)
        if M1 != M2:
            return -1 if M1 < M2 else 1
        if m1 != m2:
            return -1 if m1 < m2 else 1
        if p1 != p2:
            return -1 if p1 < p2 else 1
        if pre1 is None and pre2 is None:
            return 0
        if pre1 is None:
            return 1
        if pre2 is None:
            return -1
        for i in range(min(len(pre1), len(pre2))):
            c = compare_id(pre1[i], pre2[i])
            if c != 0:
                return c
        if len(pre1) != len(pre2):
            return -1 if len(pre1) < len(pre2) else 1
        return 0

    indexed = list(enumerate(versions))
    def full_cmp(a, b):
        c = compare(a[1], b[1])
        if c != 0:
            return c
        return a[0] - b[0]
    indexed.sort(key=functools.cmp_to_key(full_cmp))
    return [v for _, v in indexed]

